const b = $input.first().json.body || {};
const CH = ["facebook","tiktok","email"];
const channel = typeof b.channel === "string" ? b.channel.trim().toLowerCase() : "";
const topic = typeof b.topic === "string" ? b.topic.trim() : "";
const notes = typeof b.notes === "string" ? b.notes.trim().slice(0, 2000) : "";
const errors = [];
if (!CH.includes(channel)) errors.push("channel must be one of facebook, tiktok, email");
if (!topic || topic.length > 300) errors.push("topic must be a non-empty string up to 300 characters");
if (b.notes !== undefined && typeof b.notes !== "string") errors.push("notes must be a string");
return [{ json: { valid: errors.length === 0, errors, request: { channel, topic, notes } } }];

const req = $('Validate request').first().json.request;
let d;
try {
  let raw = ($json.content?.[0]?.text || "").trim().replace(/^```(?:json)?/i,"").replace(/```$/,"").trim();
  const m = raw.match(/\{[\s\S]*\}/);
  const o = JSON.parse(m ? m[0] : raw);
  d = {
    headline: String(o.headline || ""),
    body: String(o.body || ""),
    hashtags: Array.isArray(o.hashtags) ? o.hashtags.map(String).slice(0, 15) : [],
    suggested_timing: String(o.suggested_timing || ""),
    needs_human_reason: String(o.needs_human_reason || "")
  };
  if (!d.body) throw new Error("empty body");
} catch (e) {
  d = { headline: "", body: "", hashtags: [], suggested_timing: "", needs_human_reason: ($json.error ? "Anthropic request failed after retries; write this draft by hand." : "Model output could not be parsed; write this draft by hand.") };
}
const draftText = [
  "Channel: " + req.channel,
  d.headline && ("Headline: " + d.headline),
  d.body && ("Body:\n" + d.body),
  d.hashtags.length && ("Hashtags: " + d.hashtags.join(" ")),
  d.suggested_timing && ("Suggested timing: " + d.suggested_timing),
  d.needs_human_reason && ("NEEDS HUMAN: " + d.needs_human_reason)
].filter(Boolean).join("\n\n");
return [{ json: { has_draft: d.body.trim().length > 0, req, draft: d, draftText, title: ("Marketing (" + req.channel + "): " + req.topic).slice(0, 150) } }];

const TITLE = $json.title, AGENT = 'Marketer', TYPE = 'Content', DRAFT = $json.draftText, RELATED = '';

// Notion rich-text items hold at most 2000 chars, so Draft is written as several rich_text items of <=1900 chars.
// Concatenating the items' plain_text (what QA does) gives back the exact original text. Nothing is truncated.
const MAX = 1900;
const chunk = (s) => {
  const out = [];
  let i = 0;
  while (i < s.length) {
    let end = Math.min(i + MAX, s.length);
    if (end < s.length) { const c = s.charCodeAt(end - 1); if (c >= 0xD800 && c <= 0xDBFF) end -= 1; } // do not split a surrogate pair
    out.push(s.slice(i, end));
    i = end;
  }
  return out;
};
const rich = (s) => chunk(String(s)).map(c => ({ type: 'text', text: { content: c } }));
const body = {
  parent: { database_id: 'a807f4c25dfe4ce388626726b7d99f6d' },
  properties: {
    'Title': { title: [{ type: 'text', text: { content: String(TITLE).slice(0, 150) } }] },
    'Agent': { select: { name: AGENT } },
    'Type': { select: { name: TYPE } },
    'Draft': { rich_text: rich(DRAFT) },
    'Status': { select: { name: 'Awaiting Approval' } },
    'QA Result': { select: { name: 'Not checked' } },
    'Related Job': { rich_text: rich(String(RELATED).slice(0, 1900)) }
  }
};
return [{ json: { notionBody: body } }];
